def at_least_k(lits, k):
    """Generate clauses that at least k literals are true using sequential counter"""
    n_lits = len(lits)
    if k <= 0:
        return []
    if k > n_lits:
        # Unsatisfiable: need a contradiction
        return [[lits[0]], [-lits[0]]]

    clauses = []
    # Create auxiliary variables
    next_var = max(abs(l) for l in lits) + 1
    s = {}
    for i in range(1, n_lits + 1):
        for j in range(1, k + 1):
            s[(i,j)] = next_var
            next_var += 1

    # Clause (1): ¬l_i ∨ s_{i,1}
    for i in range(1, n_lits + 1):
        clauses.append([-lits[i-1], s[(i,1)]])

    # Clause (2): ¬s_{i-1,j} ∨ s_{i,j}
    for i in range(2, n_lits + 1):
        for j in range(1, k + 1):
            clauses.append([-s[(i-1,j)], s[(i,j)]])

    # Clause (3): ¬l_i ∨ ¬s_{i-1,j-1} ∨ s_{i,j}
    for i in range(2, n_lits + 1):
        for j in range(2, k + 1):
            clauses.append([-lits[i-1], -s[(i-1,j-1)], s[(i,j)]])

    # Clause (4): s_{n,k} (at least k true)
    clauses.append([s[(n_lits, k)]])

    # Wait, I also need: ¬s_{i-1,j} ∨ ¬l_i ∨ s_{i,j}? No that's redundant
